CREATE TABLE IF NOT EXISTS advertisements (id TEXT PRIMARY KEY, input_type TEXT NOT NULL, source_url TEXT, raw_text TEXT, retrieval_status TEXT NOT NULL, observed_at TEXT NOT NULL, synthetic INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS claims (id TEXT PRIMARY KEY, advertisement_id TEXT NOT NULL, claim_type TEXT NOT NULL, value TEXT, extraction_state TEXT NOT NULL, FOREIGN KEY(advertisement_id) REFERENCES advertisements(id));
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, advertisement_id TEXT NOT NULL, claim_type TEXT NOT NULL, source_url TEXT, source_type TEXT NOT NULL, observed_at TEXT NOT NULL, source_timestamp TEXT, retrieval_status TEXT NOT NULL, summary TEXT NOT NULL, evidence_state TEXT NOT NULL, rationale TEXT NOT NULL, FOREIGN KEY(advertisement_id) REFERENCES advertisements(id));
CREATE TABLE IF NOT EXISTS lineage_relationships (id TEXT PRIMARY KEY, left_advertisement_id TEXT NOT NULL, right_advertisement_id TEXT NOT NULL, relationship TEXT NOT NULL, similarity REAL NOT NULL, rationale TEXT NOT NULL, reviewer_decision TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS annotations (id TEXT PRIMARY KEY, advertisement_id TEXT NOT NULL, dimension TEXT NOT NULL, label TEXT NOT NULL, rationale TEXT NOT NULL, annotator TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS model_runs (id TEXT PRIMARY KEY, model_name TEXT NOT NULL, config_json TEXT NOT NULL, metrics_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_records (id TEXT PRIMARY KEY, advertisement_id TEXT, source_type TEXT NOT NULL, source_url TEXT, content_hash TEXT, raw_content BLOB, extracted_text TEXT, retrieval_status TEXT NOT NULL, observed_at TEXT NOT NULL, warnings_json TEXT NOT NULL DEFAULT '[]', FOREIGN KEY(advertisement_id) REFERENCES advertisements(id));
